package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {









    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1E10"));
        assertTrue(NumberUtils.isNumber("1.2e-5"));
        assertTrue(NumberUtils.isNumber("1.2E+5"));
        assertFalse(NumberUtils.isNumber("e10")); // No digit before E
        assertFalse(NumberUtils.isNumber("1e"));  // Ends in E
        assertFalse(NumberUtils.isNumber("1e+")); // Ends in sign after E
        assertFalse(NumberUtils.isNumber("1e1.2")); // Dec in exponent
        assertFalse(NumberUtils.isNumber("1e1e1")); // Two Es
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        assertTrue(NumberUtils.isNumber("123.45f"));

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        // l/L not allowed with exponent based on code: return foundDigit && !hasExp;
        assertFalse(NumberUtils.isNumber("1e10l"));
        assertFalse(NumberUtils.isNumber("1e10L"));

        // Invalid qualifiers
        assertFalse(NumberUtils.isNumber("123x"));
        assertFalse(NumberUtils.isNumber("123.45x"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {













    @Test
    public void testIsNumber_EdgeCasesAndFailures() {
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("12a3"));
        assertFalse(NumberUtils.isNumber(" "));
        assertFalse(NumberUtils.isNumber("-"));
        assertFalse(NumberUtils.isNumber("+"));
        assertFalse(NumberUtils.isNumber("1e-"));
        assertFalse(NumberUtils.isNumber("1.2.3"));
        assertFalse(NumberUtils.isNumber("1e1.2"));

        // Testing the logic: if (i < sz + 1 && allowSigns && !foundDigit)
        // This part of the loop handles the case where a sign follows an 'E'
        assertTrue(NumberUtils.isNumber("1E-5"));

        // Test trailing dot logic
        // if (chars[i] >= '.') { if (hasDecPoint || hasExp) return false; return foundDigit; }
        assertTrue(NumberUtils.isNumber("123.")); 
        assertFalse(NumberUtils.isNumber("1e2.")); // hasExp is true, so returns false
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {















    @Test
    public void testIsNumber_ComplexScenarios() {
        // Test sign at start
        assertTrue(NumberUtils.isNumber("-0x123"));

        // Test decimal point and digits
        assertTrue(NumberUtils.isNumber("0.1"));

        // Test invalid characters in middle
        assertFalse(NumberUtils.isNumber("12 3"));

        // Test multiple signs
        assertFalse(NumberUtils.isNumber("12+-3"));
        assertFalse(NumberUtils.isNumber("1e+-3"));
    }
}
